public var windowIDs: [WindowID] {
    switch self {
    case .empty:
        return []
    case .leaf(let id):
        return [id]
    case .split(_, _, let first, let second):
        return first.windowIDs + second.windowIDs
    }
}

findings.remediation_code:
public var windowIDs: [WindowID] {
    var result: [WindowID] = []
    collectWindowIDs(into: &result)
    return result
}

private func collectWindowIDs(into result: inout [WindowID]) {
    switch self {
    case .empty: return
    case .leaf(let id): result.append(id)
    case .split(_, _, let first, let second):
        first.collectWindowIDs(into: &result)
        second.collectWindowIDs(into: &result)
    }
}

